vec4 GetBlur1(vec2 uv) { return texture(sampler_blur1, uv); }
vec4 GetBlur2(vec2 uv) { return texture(sampler_blur2, uv); }
vec4 GetBlur3(vec2 uv) { return texture(sampler_blur3, uv); }


void main() {
  vec4 ret = vec4(0.0);
  vec2 uv = vUv;
  float rad = vRadius;

uvo = 0.5 + (vUv-0.5)*vec2(0.9,1.1);
factorA = vUv-vec2(1-0.5,0.5);
factorB = vec2(0,1024);
product = vec2( factorA.x*factorB.x - factorA.y*factorB.y, factorA.x*factorB.y + factorA.y*factorB.x);
numerator = vec2(1,0);
denominator = product;
fraction = vec2( numerator.x*denominator.x + numerator.y*denominator.y,   // the fractions real part
                   numerator.y*denominator.x - numerator.x*denominator.y)/  // the fractions imaginary part
                   (denominator.x*denominator.x + denominator.y*denominator.y);
vUv = fraction.yx*vec2(-1,1)*64;
vUv = mix(0.5 + (uvo-0.5)*2,vUv+0.5,0.5);
vUv = 0.5 + (1.0 - abs( fract( vUv * 0.5 ) * 2 - 1.0 )-0.5); // Eo.S. mirror code with cutted borders

    vec2 d = uTexSize.zw*4;
    vec3 dx = ( 2*GetBlur1(vUv+vec2(1,0)*d)-2*GetBlur1(vUv-vec2(1,0)*d) )*0.5;
    vec3 dy = ( 2*GetBlur1(vUv+vec2(0,1)*d)-2*GetBlur1(vUv-vec2(0,1)*d) )*0.5;

vec2 uv_x = vUv - vec2(dx.y,dy.y)*uTexSize.zw*128;
ret = GetBlur2(uv_x).x*clamp01(1-GetPixel(vUv).y)*pow(hue_shader.yxz,8)*3;
ret = mix(ret,pow(hue_shader.yzx,8)*1.4,GetPixel(uv_x).x*0.8 + GetBlur1(uv_x).x);
ret = mix(ret,1,pow(hue_shader,8)*GetPixel(clamp01(vUv - vec2(dx.z,dy.z)*2*0)).y*1.2);
ret *= clamp01(1-GetPixel(vUv).z);

  fragColor = ret;
}

