void main() {
  vec4 ret = vec4(0.0);
  vec2 uv = vUv;
  float rad = vRadius;

float corr = uTexSize.xy*texsize_noise_lq.zw;
//vec2 uv1 = vec2(vUv.x-0.5,vUv.y-0.5);//*uAspect.xy;


vec2 hor = vec2 (.003,0);
vec2 ver = vec2 (0,.003);
float dx = lum(texture(sampler_main,vUv+hor) - texture(sampler_main,vUv-hor));
float dy = lum(texture(sampler_main,vUv+ver) - texture(sampler_main,vUv-ver));

vec2 dz = vec2 (dx,dy);


vec3 noise2 = lum(texture(sampler_noise_hq,
                    vUv+ .0*uTime+.01*rand_frame));
noise2 = 2*(noise2-.5);

vec3 noise3 = lum(texture(sampler_noise_lq,
                    corr*vUv*.5 + 0.1*rand_frame));


vec3 blur = GetBlur1(fract(vUv));
vec3 blur2 = GetBlur1(fract(vUv*noise3));

vec2 zz = (blur*noise3)* (dz);

double3 crisp = texture(sampler_main,vUv+zz*.03);
crisp += noise2*(.01) +.02 ;


vec3 ret1 = -0.03*blur2+ crisp - length(zz)*.0;

//ret1 -= .1*pow(vRadius,4);
ret1 -= .07*pow(vUv.x-.6,2) + .1*pow(vUv.y-.6,2);

ret = ret1 * .99 -  .01;

